def esc(t):
    t = t.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")
    t = t.replace("\\","\\\\").replace("'", "\\'").replace('"','\\"').replace("\n","\\n")
    if t.startswith("@") or t.startswith("?"): t = "\\"+t
    return t
for i, d in enumerate(["values", "values-en", "values-ru"]):
    os.makedirs(f"{R}/{d}", exist_ok=True)
    out = ['<?xml version="1.0" encoding="utf-8"?>', "<!-- Généré par gen/chaines.py -->", "<resources>"]
    if i == 0: out.append('    <string name="app_name" translatable="false">PrP</string>')
    for k, v in S.items(): out.append(f'    <string name="{k}">{esc(v[i])}</string>')
    for k, v in P.items():
        out.append(f'    <plurals name="{k}">')
        for q, t in v[i].items(): out.append(f'        <item quantity="{q}">{esc(t)}</item>')
        out.append("    </plurals>")
    out.append("</resources>")
    open(f"{R}/{d}/strings.xml", "w").write("\n".join(out) + "\n")
print(len(S), "chaînes,", len(P), "pluriels")
